-- ============================================================
-- DATABASE HASIL OLAHAN ALGORITMA SPK GEREJA
-- Judul: Hybrid DBSCAN dan AHP-TOPSIS untuk Prioritisasi Pembinaan Gereja
-- Berbasis Pemetaan Administratif Kecamatan di Kabupaten Minahasa Selatan
-- Generated: 2026-05-26 22:39:11
-- Sumber: database MySQL db_kemenag_minsel, tabel gereja dan kecamatan
-- ============================================================

CREATE DATABASE IF NOT EXISTS db_spk_gereja_hasil CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE db_spk_gereja_hasil;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS spk_metadata;
CREATE TABLE spk_metadata (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(150) NOT NULL,
  nilai TEXT,
  created_at DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS spk_bobot_kriteria;
CREATE TABLE spk_bobot_kriteria (
  id INT AUTO_INCREMENT PRIMARY KEY,
  kode_kriteria VARCHAR(80) NOT NULL,
  nama_kriteria VARCHAR(150) NOT NULL,
  bobot DECIMAL(10,6) NOT NULL,
  tipe VARCHAR(20) NOT NULL,
  keterangan TEXT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS spk_skor_status_bangunan;
CREATE TABLE spk_skor_status_bangunan (
  status_bangunan VARCHAR(30) PRIMARY KEY,
  skor_risiko DECIMAL(10,6) NOT NULL,
  jumlah_data INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS spk_evaluasi_dbscan;
CREATE TABLE spk_evaluasi_dbscan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  total_data INT NOT NULL,
  jumlah_cluster INT NOT NULL,
  jumlah_outlier INT NOT NULL,
  persentase_outlier DECIMAL(10,4) NOT NULL,
  silhouette_score DECIMAL(10,6),
  eps DECIMAL(10,4) NOT NULL,
  min_samples INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS spk_profil_cluster;
CREATE TABLE spk_profil_cluster (
  id INT AUTO_INCREMENT PRIMARY KEY,
  cluster_label VARCHAR(30) NOT NULL,
  jumlah_data INT NOT NULL,
  skor_rata_rata DECIMAL(12,6) NOT NULL,
  rata_jumlah_umat DECIMAL(12,4) NOT NULL,
  rata_risiko_bangunan DECIMAL(12,6) NOT NULL,
  rata_kesenjangan_pelayan DECIMAL(12,4) NOT NULL,
  rata_tekanan_wilayah DECIMAL(12,4) NOT NULL,
  prioritas_tinggi INT NOT NULL,
  prioritas_sedang INT NOT NULL,
  prioritas_rendah INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS spk_rekap_kecamatan;
CREATE TABLE spk_rekap_kecamatan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  peringkat INT NOT NULL,
  kecamatan VARCHAR(100) NOT NULL,
  jumlah_gereja INT NOT NULL,
  skor_wilayah DECIMAL(12,6) NOT NULL,
  skor_persen DECIMAL(12,4) NOT NULL,
  prioritas_wilayah VARCHAR(20) NOT NULL,
  jumlah_prioritas_tinggi INT NOT NULL,
  jumlah_prioritas_sedang INT NOT NULL,
  jumlah_prioritas_rendah INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS spk_sensitivitas_dbscan;
CREATE TABLE spk_sensitivitas_dbscan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  eps DECIMAL(10,4) NOT NULL,
  min_samples INT NOT NULL,
  jumlah_cluster INT NOT NULL,
  jumlah_outlier INT NOT NULL,
  persentase_outlier DECIMAL(10,4) NOT NULL,
  silhouette_score DECIMAL(10,6),
  distribusi_cluster TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS spk_ranking_gereja;
CREATE TABLE spk_ranking_gereja (
  id INT AUTO_INCREMENT PRIMARY KEY,
  peringkat INT NOT NULL,
  gereja_id BIGINT NOT NULL,
  nama_gereja VARCHAR(200) NOT NULL,
  kecamatan VARCHAR(100) NOT NULL,
  kelurahan_desa VARCHAR(150),
  jumlah_umat_l INT,
  jumlah_umat_p INT,
  jumlah_umat INT NOT NULL,
  nama_pimpinan VARCHAR(200),
  status_bangunan VARCHAR(30),
  jumlah_pdt INT,
  jumlah_pdm INT,
  kriteria_jumlah_umat DECIMAL(12,4) NOT NULL,
  kriteria_risiko_bangunan DECIMAL(12,6) NOT NULL,
  kriteria_kesenjangan_pelayan DECIMAL(12,4) NOT NULL,
  kriteria_tekanan_wilayah DECIMAL(12,4) NOT NULL,
  bobot_jumlah_umat DECIMAL(12,6) NOT NULL,
  bobot_risiko_bangunan DECIMAL(12,6) NOT NULL,
  bobot_kesenjangan_pelayan DECIMAL(12,6) NOT NULL,
  bobot_tekanan_wilayah DECIMAL(12,6) NOT NULL,
  skor_topsis DECIMAL(12,8) NOT NULL,
  skor_persen DECIMAL(12,4) NOT NULL,
  prioritas VARCHAR(20) NOT NULL,
  cluster_label VARCHAR(30) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SET FOREIGN_KEY_CHECKS = 1;
